  const from = document.querySelector('#due-from').value.trim();
  const through = document.querySelector('#due-through').value.trim();
  const valid = value => {
    if (!value) return true;
    if (!/^\\d{4}-\\d{2}-\\d{2}$/.test(value)) return false;
    const [year, month, day] = value.split('-').map(Number);
    const leap = year % 4 === 0 && (year % 100 !== 0 || year % 400 === 0);
    const days = [31, leap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
    return year >= 1 && month >= 1 && month <= 12 && day >= 1 && day <= (days[month - 1] || 0);
  };
  if (!valid(from) || !valid(through)) { alert.textContent = 'Due range must use valid YYYY-MM-DD dates'; return; }
  if (from && through && from > through) { alert.textContent = 'Due from must not be after Due through'; return; }
  appliedFrom = from; appliedThrough = through; alert.textContent = ''; renderTasks();
});
